package com.enterprise.patterns;

import org.springframework.stereotype.Component;
import java.util.Map;
import java.util.Set;

// 1. Strategy Pattern Interface
public interface PricingStrategy {
    BigDecimal calculatePrice(Order order);
}

@Component("VIP")
class VipPricingStrategy implements PricingStrategy {
    public BigDecimal calculatePrice(Order order) {
        return order.getBaseAmount().multiply(new BigDecimal("0.85"));
    }
}

// 2. Template Method Abstract Class
public abstract class OrderProcessingTemplate {
    // The Template Method (final to prevent overriding the skeleton)
    public final void processOrder(Order order) {
        validate(order);
        BigDecimal finalPrice = calculatePrice(order);
        saveOrder(order, finalPrice);
        notifyObservers(order);
    }

    protected abstract void validate(Order order);
    protected abstract BigDecimal calculatePrice(Order order);

    private void saveOrder(Order order, BigDecimal price) {
        // Common persistence logic
    }

    protected abstract void notifyObservers(Order order);
}

// 3. Command Pattern Interface
public interface Command {
    void execute();
}

// 4. Observer Pattern Event Publisher simulation
@Component
public class OrderProcessorContext extends OrderProcessingTemplate {
    private final Map<String, PricingStrategy> strategies;
    private final Set<OrderObserver> observers;

    public OrderProcessorContext(Map<String, PricingStrategy> strategies, Set<OrderObserver> observers) {
        this.strategies = strategies;
        this.observers = observers;
    }

    @Override
    protected void validate(Order order) { /* Validation logic */ }

    @Override
    protected BigDecimal calculatePrice(Order order) {
        PricingStrategy strategy = strategies.getOrDefault(order.getCustomerType(), strategies.get("DEFAULT"));
        return strategy.calculatePrice(order);
    }

    @Override
    protected void notifyObservers(Order order) {
        observers.forEach(obs -> obs.onOrderProcessed(order));
    }
}
